const err = $json.execution.error || {};
const wf = $json.workflow || {};

const alertText = `
🚨 <b>[ALERT] EKSEKUSI WORKFLOW GAGAL!</b>

🏢 <b>Sistem:</b> Ziyan Automation Systems (ZAS)
📋 <b>Nama Workflow:</b> ${wf.name || 'Unknown'}
🆔 <b>Workflow ID:</b> <code>${wf.id || '-'}</code>
⚠️ <b>Pesan Error:</b> <code>${err.message || 'Unknown Execution Error'}</code>
⏱️ <b>Waktu Kejadian:</b> ${new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })} WIB
🔗 <b>Link Investigasi:</b> <a href="${$env.N8N_INSTANCE_URL || 'http://localhost:5678'}/workflow/${wf.id}/executions/${$json.execution.id}">Lihat Detail Execution</a>
`;

return [{
  json: {
    alert_message: alertText,
    workflow_name: wf.name,
    error_message: err.message,
    execution_id: $json.execution.id
  }
}];
